import java.util.Scanner;
public class JCheckProductCode1 {
	public static void main(String[] args) {
		JCheckProductCode1 p1 = new JCheckProductCode1();
		p1.checkProductCode();
	}
	//Khutwa 1: Ta'reef al-tariqa
	public void checkProductCode() {
		//Khutwa 1.1: Ta'reef al-mutaghayyirat allati nahtaajuha lil-i3dad
	    int valid = 0;
	    int banned = 0;
	    //Khutwa 1.2: Utlub madkhal sahih ma dam al-mustakhdim lam yadkhul STOP; itha dakhal STOP faqaf
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil ramz al-muntaj:");
		String code = scan.next();	    
	    while ( ! code.equals("STOP") ) {
	    	 //Khutwa 1.2.1: Hugawir al-kod allathi qad yurmi istithna' dakhil qit'at try
	        try {
	            char zone = code.charAt(9);
	            valid += 1;
	            if (zone == 'R' ) {
	                banned += 1;
	            }
	        }
	        //Khutwa 1.2.2: Ta3amul ma3a jami3 al-istithna'at al-mumkina fi qit'at try
	       catch (IndexOutOfBoundsException ex ) {                    
	            System.out.println("Toul ramz ghair munasib.");
	       } 
			System.out.println("Adkhil ramz al-muntaj:");
			code = scan.next();
	    }
	    //Khutwa 1.3: Taba3 al-nateeja    
	    System.out.println("# adad al-rumuz al-sahihah al-mudkhalah: " + valid);
	    System.out.println("# adad al-rumuz al-mamnua: "+ banned);
	}
}
